import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        r = []
        c = []

        for _ in range(n):
            r.append(int(next(iterator)))
        for _ in range(n):
            c.append(int(next(iterator)))

        points = list(zip(r, c))
        points.sort()

        total_cost = 0
        curr_r, curr_c = 1, 1

        for target_r, target_c in points:
            if target_r < curr_r:
                continue

            diff = target_r - curr_r
            if diff % 2 == 0:
                if abs(target_c - curr_c) > diff:
                    total_cost += 1
                    curr_c += 1
                    if curr_c > target_c:
                        curr_c -= 1
                else:
                    pass
            else:
                if abs(target_c - curr_c) > diff:
                     total_cost += 1
                     curr_c += 1
                     if curr_c > target_c:
                         curr_c -= 1
                else:
                    pass

            curr_r = target_r
            curr_c = target_c

        results.append(str(total_cost))

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
